    "src/utils/UUPSUpgradeable.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity =0.7.6;

/**
 * @dev Minimal Solidity 0.7-compatible UUPS implementation used by EmptyProxy.
 * Storage slots and the rollback test follow ERC-1967 / OpenZeppelin's UUPS
 * implementation.
 */
abstract contract UUPSUpgradeable {
    bytes32 private constant _IMPLEMENTATION_SLOT = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;
    bytes32 private constant _ROLLBACK_SLOT = 0x4910fdfa16fed3260ed0e7147f7cc6da11a60208b5b9406d12a635614ffd9143;

    address private immutable _self = address(this);

    event Upgraded(address indexed implementation);

    modifier onlyProxy() {
        require(address(this) != _self, "Function must be called through delegatecall");
        require(_getImplementation() == _self, "Function must be called through active proxy");
        _;
    }

    modifier notDelegated() {
        require(address(this) == _self, "UUPSUpgradeable: must not be called through delegatecall");
        _;
    }

    function proxiableUUID() external view notDelegated returns (bytes32) {
        return _IMPLEMENTATION_SLOT;
    }

    function upgradeTo(address newImplementation) external virtual onlyProxy {
        _authorizeUpgrade(newImplementation);
        _upgradeToAndCallSecure(newImplementation, new bytes(0), false);
    }

    function upgradeToAndCall(address newImplementation, bytes calldata data) external payable virtual onlyProxy {
        _authorizeUpgrade(newImplementation);
        _upgradeToAndCallSecure(newImplementation, data, true);
    }

    function _authorizeUpgrade(address newImplementation) internal virtual;

    function _upgradeToAndCallSecure(address newImplementation, bytes memory data, bool forceCall) private {
        address oldImplementation = _getImplementation();

        _upgradeToAndCall(newImplementation, data, forceCall);

        if (!_getBoolean(_ROLLBACK_SLOT)) {
            _setBoolean(_ROLLBACK_SLOT, true);
            (bool success,) =
                newImplementation.delegatecall(abi.encodeWithSignature("upgradeTo(address)", oldImplementation));
            require(success, "ERC1967Upgrade: upgrade breaks further upgrades");
            _setBoolean(_ROLLBACK_SLOT, false);

            require(oldImplementation == _getImplementation(), "ERC1967Upgrade: upgrade breaks further upgrades");
            _upgradeToAndCall(newImplementation, new bytes(0), false);
        }
    }

    function _upgradeToAndCall(address newImplementation, bytes memory data, bool forceCall) private {
        _setImplementation(newImplementation);
        emit Upgraded(newImplementation);

        if (data.length > 0 || forceCall) {
            (bool success, bytes memory returndata) = newImplementation.delegatecall(data);
            if (!success) {
                assembly {
                    revert(add(returndata, 32), mload(returndata))
                }
            }
        }
    }

    function _getImplementation() private view returns (address implementation) {
        bytes32 slot = _IMPLEMENTATION_SLOT;
        assembly {
            implementation := sload(slot)
        }
    }

    function _setImplementation(address newImplementation) private {
        uint256 size;
        assembly {
            size := extcodesize(newImplementation)
        }
        require(size > 0, "ERC1967: new implementation is not a contract");

        bytes32 slot = _IMPLEMENTATION_SLOT;
        assembly {
            sstore(slot, newImplementation)
        }
    }

    function _getBoolean(bytes32 slot) private view returns (bool value) {
        assembly {
            value := sload(slot)
        }
    }

    function _setBoolean(bytes32 slot, bool value) private {
        assembly {
            sstore(slot, value)
        }
    }
}
